/// Calls `f` on every registry entry compiled into this build.
pub(crate) fn for_each_op_entry(mut f: impl FnMut(&OpEntry)) {
    for entry in OP_REGISTRY {
        f(entry);
    }
    #[cfg(feature = "aot-load")]
    {
        for entry in OP_REGISTRY_FEATURE_AOT_LOAD {
            f(entry);
        }
    }
    #[cfg(feature = "simd")]
    {
        for entry in OP_REGISTRY_FEATURE_SIMD {
            f(entry);
        }
    }
    #[cfg(feature = "threads")]
    {
        for entry in OP_REGISTRY_FEATURE_THREADS {
            f(entry);
        }
    }
}

const fn hash_op_table(mut hash: u64, table: &[OpEntry]) -> u64 {
    let mut i = 0;
    while i < table.len() {
        let name = table[i].name.as_bytes();
        let mut j = 0;
        while j < name.len() {
            hash ^= name[j] as u64;
            hash = hash.wrapping_mul(0x100_0000_01b3);
            j += 1;
        }
        hash ^= table[i].id as u64;
        hash = hash.wrapping_mul(0x100_0000_01b3);
        i += 1;
    }
    hash
}

/// FNV-1a hash of the (id, name) pairs compiled into this build.
/// Part of the precompiled artifact fingerprint: two builds whose
/// registries differ in any entry hash differently.
pub(crate) const OP_TABLE_HASH: u64 = {
    let mut hash = 0xcbf2_9ce4_8422_2325;
    hash = hash_op_table(hash, OP_REGISTRY);
    #[cfg(feature = "aot-load")]
    {
        hash = hash_op_table(hash, OP_REGISTRY_FEATURE_AOT_LOAD);
    }
    #[cfg(feature = "simd")]
    {
        hash = hash_op_table(hash, OP_REGISTRY_FEATURE_SIMD);
    }
    #[cfg(feature = "threads")]
    {
        hash = hash_op_table(hash, OP_REGISTRY_FEATURE_THREADS);
    }
    hash
};
